// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
} from '../remotionShim';


export type TankRevealProps = Record<string, any>;

const TankReveal: React.FC<TankRevealProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  tankPrimaryColor = "#A39171",
  tankSecondaryColor = "#2C2C2C",
  accentColor = "#00FF41",
  showHUD = true,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling based on 1080p reference
  const baseScale = Math.min(width / 1920, height / 1080);
  const tankScale = 1.2 * baseScale;

  // Raw SVG dimensions
  const tankSvgWidth = 800;
  const tankSvgHeight = 300;
  const scaledWidth = tankSvgWidth * tankScale;
  const scaledHeight = tankSvgHeight * tankScale;

  // Animation layout math
  const startX = -scaledWidth - width * 0.2;
  const endX = (width - scaledWidth) / 2;
  const currentY = (height - scaledHeight) / 2;

  // Timings
  const arrivalDuration = 70;

  // Interpolations
  const arrivalProgress = interpolate(frame, [0, arrivalDuration], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  const currentX = interpolate(
    arrivalProgress,
    [0, 1],
    [startX, endX]
  );

  // Vibration and Suspension
  const movementVelocity = interpolate(
    frame,
    [arrivalDuration - 25, arrivalDuration],
    [1, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  const vibrationY =
    Math.sin(frame * 2.5) * 2 * movementVelocity * baseScale;

  // Tank Track & Wheel Rotation Math
  // Visual movement in SVG space
  const svgX = currentX / tankScale;
  // Rotate wheels based on linear distance (360deg per ~150px circumference)
  const wheelRotation = svgX * 2.4;
  const trackOffset = -svgX;

  // Cannon Aiming (elevates slightly after stopping)
  const cannonAngle = interpolate(
    frame,
    [arrivalDuration + 5, arrivalDuration + 35],
    [0, -6],
    {
      easing: Easing.inOut(Easing.ease),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // HUD Box Logic
  const boxScale = interpolate(
    frame,
    [arrivalDuration, arrivalDuration + 20],
    [1.05, 1],
    {
      easing: Easing.out(Easing.exp),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );
  const boxOpacity = interpolate(
    frame,
    [arrivalDuration, arrivalDuration + 15],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Dust Particles Array Generation
  const particles = Array.from({ length: 45 }).map((_, i) => {
    const spawnFrame = i * 1.5;
    if (spawnFrame > arrivalDuration - 5) return null;

    const spawnProgress = interpolate(spawnFrame, [0, arrivalDuration], [0, 1], {
      easing: Easing.out(Easing.cubic),
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    });
    const spawnXScreen = startX + spawnProgress * (endX - startX);

    // Track rear in screen space
    const rearX = spawnXScreen + 160 * tankScale;
    const rearY = currentY + 280 * tankScale;

    // Add some organic spread
    const exactSpawnX = rearX + (i % 4) * 25 * baseScale;
    const exactSpawnY = rearY - (i % 3) * 10 * baseScale;

    const age = frame - spawnFrame;
    if (age < 0 || age > 50) return null;

    const size = interpolate(age, [0, 50], [20 * baseScale, 180 * baseScale]);
    const opacity = interpolate(age, [0, 10, 30, 50], [0, 0.4, 0.2, 0]);
    const driftY = age * -1.5 * baseScale;
    const driftX = age * -1.0 * baseScale;

    return (
      <div
        key={i}
        style={{
          position: "absolute",
          left: exactSpawnX + driftX,
          top: exactSpawnY + driftY,
          width: size,
          height: size,
          borderRadius: "50%",
          backgroundColor: "#8C7A5E",
          opacity: opacity,
          transform: "translate(-50%, -50%)",
          filter: `blur(${12 * baseScale}px)`,
          mixBlendMode: "screen",
          pointerEvents: "none",
          transition: "none",
        }}
      />
    );
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Dust Particles rendered behind tank */}
      {particles}

      {/* Tank Container */}
      <div
        style={{
          position: "absolute",
          left: currentX,
          top: currentY + vibrationY,
          width: tankSvgWidth,
          height: tankSvgHeight,
          transform: `scale(${tankScale})`,
          transformOrigin: "top left",
          transition: "none",
        }}
      >
        <svg
          width={tankSvgWidth}
          height={tankSvgHeight}
          viewBox={`0 0 ${tankSvgWidth} ${tankSvgHeight}`}
          style={{ overflow: "visible" }}
        >
          {/* Hull Polygon */}
          <polygon
            points="150,230 150,160 300,160 350,140 580,140 730,200 700,240 180,240"
            fill={tankPrimaryColor}
          />
          <polygon
            points="150,230 150,200 720,200 700,240 180,240"
            fill="#000"
            opacity={0.15}
          />

          {/* Cannon Base (Mantlet) */}
          <polygon points="530,130 550,130 560,125 560,105 550,100 530,100" fill={tankSecondaryColor} />

          {/* Cannon Assembly (Rotates) */}
          <g style={{ transformOrigin: "550px 115px", transform: `rotate(${cannonAngle}deg)` }}>
            {/* Main Barrel */}
            <rect x="550" y="109" width="300" height="12" fill={tankPrimaryColor} />
            <rect x="550" y="115" width="300" height="6" fill="#000" opacity={0.2} />
            {/* Bore Evacuator */}
            <rect x="680" y="105" width="50" height="20" rx="3" fill={tankPrimaryColor} />
            {/* Muzzle Reference Sensor */}
            <rect x="840" y="105" width="10" height="6" fill={tankSecondaryColor} />
          </g>

          {/* Turret Main Shape */}
          <polygon points="350,140 500,140 550,90 350,90 200,90 200,120 280,140" fill={tankPrimaryColor} />
          
          {/* Turret Shading/Armor Lines */}
          <polygon points="500,140 550,90 480,90 450,140" fill="#000" opacity={0.1} />
          <polygon points="350,140 350,90 200,90 200,120 280,140" fill="#000" opacity={0.15} />
          
          {/* Turret Details */}
          <rect x="180" y="95" width="20" height="25" fill={tankSecondaryColor} />
          <line x1="220" y1="90" x2="200" y2="20" stroke={tankSecondaryColor} strokeWidth={2} />
          <line x1="280" y1="90" x2="270" y2="10" stroke={tankSecondaryColor} strokeWidth={3} />

          {/* Side Skirts (Armor) */}
          <polygon points="140,220 720,200 690,250 160,250" fill={tankPrimaryColor} opacity={0.98} />
          {/* Skirt Panel Gaps */}
          {[200, 280, 360, 440, 520, 600].map((cx) => (
            <line key={`skirt-${cx}`} x1={cx} y1={212} x2={cx - 10} y2={250} stroke="#000" strokeWidth={2} opacity={0.3} />
          ))}

          {/* Tracks Base Darkness */}
          <path d="M 160,205 L 680,210 Q 710,210 710,240 L 620,288 L 220,288 L 160,265 Q 130,250 130,235 Q 130,205 160,205 Z" fill="#0a0a0a" />

          {/* Wheels Array */}
          {[240, 300, 360, 420, 480, 540, 600].map((cx) => (
            <g key={`wheel-${cx}`} style={{ transformOrigin: `${cx}px 263px`, transform: `rotate(${wheelRotation}deg)` }}>
              <circle cx={cx} cy={263} r={22} fill={tankSecondaryColor} />
              <circle cx={cx} cy={263} r={16} fill="none" stroke="#444" strokeWidth={3} />
              <line x1={cx - 16} y1={263} x2={cx + 16} y2={263} stroke="#1a1a1a" strokeWidth={4} />
              <line x1={cx} y1={263 - 16} x2={cx} y2={263 + 16} stroke="#1a1a1a" strokeWidth={4} />
              <circle cx={cx} cy={263} r={6} fill="#111" />
            </g>
          ))}

          {/* Rear Drive Sprocket */}
          <g style={{ transformOrigin: "160px 235px", transform: `rotate(${wheelRotation * 1.1}deg)` }}>
            <circle cx={160} cy={235} r={20} fill={tankSecondaryColor} />
            {Array.from({ length: 10 }).map((_, i) => (
              <line
                key={`sprocket-${i}`}
                x1={160}
                y1={235}
                x2={160 + 24 * Math.cos((i * Math.PI) / 5)}
                y2={235 + 24 * Math.sin((i * Math.PI) / 5)}
                stroke={tankSecondaryColor}
                strokeWidth={4}
              />
            ))}
            <circle cx={160} cy={235} r={8} fill="#111" />
          </g>

          {/* Front Idler */}
          <g style={{ transformOrigin: "680px 240px", transform: `rotate(${wheelRotation * 1.2}deg)` }}>
            <circle cx={680} cy={240} r={18} fill={tankSecondaryColor} />
            <line x1={666} y1={240} x2={694} y2={240} stroke="#111" strokeWidth={4} />
            <line x1={680} y1={226} x2={680} y2={254} stroke="#111" strokeWidth={4} />
            <circle cx={680} cy={240} r={5} fill="#111" />
          </g>

          {/* Track Outer Outline (Animated Treads) */}
          <path
            d="M 160,205 L 680,210 Q 710,210 710,240 L 620,288 L 220,288 L 160,265 Q 130,250 130,235 Q 130,205 160,205 Z"
            fill="none"
            stroke={tankSecondaryColor}
            strokeWidth={8}
            strokeDasharray="12 6"
            strokeDashoffset={trackOffset}
            opacity={0.8}
          />
        </svg>
      </div>

      {/* Military HUD Overlay */}
      {showHUD && (
        <div
          style={{
            position: "absolute",
            left: endX - 20 * baseScale,
            top: currentY - 20 * baseScale,
            width: scaledWidth + 40 * baseScale,
            height: scaledHeight + 40 * baseScale,
            opacity: boxOpacity,
            transform: `scale(${boxScale})`,
            transformOrigin: "center center",
            pointerEvents: "none",
            transition: "none",
          }}
        >
          {/* Target Box Corners */}
          <div style={{ position: "absolute", top: 0, left: 0, width: 30 * baseScale, height: 30 * baseScale, borderTop: `4px solid ${accentColor}`, borderLeft: `4px solid ${accentColor}` }} />
          <div style={{ position: "absolute", top: 0, right: 0, width: 30 * baseScale, height: 30 * baseScale, borderTop: `4px solid ${accentColor}`, borderRight: `4px solid ${accentColor}` }} />
          <div style={{ position: "absolute", bottom: 0, left: 0, width: 30 * baseScale, height: 30 * baseScale, borderBottom: `4px solid ${accentColor}`, borderLeft: `4px solid ${accentColor}` }} />
          <div style={{ position: "absolute", bottom: 0, right: 0, width: 30 * baseScale, height: 30 * baseScale, borderBottom: `4px solid ${accentColor}`, borderRight: `4px solid ${accentColor}` }} />
          
          {/* Crosshair guides */}
          <div style={{ position: "absolute", top: "50%", left: -20 * baseScale, width: 15 * baseScale, height: 2 * baseScale, backgroundColor: accentColor, opacity: 0.5 }} />
          <div style={{ position: "absolute", top: "50%", right: -20 * baseScale, width: 15 * baseScale, height: 2 * baseScale, backgroundColor: accentColor, opacity: 0.5 }} />
          <div style={{ position: "absolute", top: -20 * baseScale, left: "50%", width: 2 * baseScale, height: 15 * baseScale, backgroundColor: accentColor, opacity: 0.5 }} />
          <div style={{ position: "absolute", bottom: -20 * baseScale, left: "50%", width: 2 * baseScale, height: 15 * baseScale, backgroundColor: accentColor, opacity: 0.5 }} />
        </div>
      )}
    </AbsoluteFill>
  );
};

export default TankReveal;